/*
 * Message relay for the browser games (jogos.htm).
 * A state request that carries a "gm" object, for example {"gm":{"t":"k","p":1,"m":3}}, is copied as {"gm":{...}} to every
 * connected WebSocket client, the sender included (clients ignore their own messages by the "id" they put inside).
 * The board does not interpret the content: one browser runs the game, the others send it their button presses.
 * /json/info gets "gmr":1 so a page can tell that the relay is present.
 */
class GameRelayUsermod : public Usermod {
  private:
    static constexpr size_t MAX_MESSAGE = 320; // longer messages are dropped; an ESP8266 receives at most 528 bytes per WebSocket message

  public:
    void setup() override {}
    void loop() override {}

    void readFromJsonState(JsonObject& root) override {
#ifdef WLED_ENABLE_WEBSOCKETS
      JsonObject gm = root[F("gm")];
      if (gm.isNull() || !ws.count()) return;
      static char buf[MAX_MESSAGE]; // static: the WebSocket callback runs on a small stack on the ESP8266
      constexpr size_t HEAD = 6;    // length of {"gm":
      const size_t len = measureJson(gm);
      if (len + HEAD + 2 > sizeof(buf)) return;
      memcpy_P(buf, PSTR("{\"gm\":"), HEAD);
      serializeJson(gm, buf + HEAD, sizeof(buf) - HEAD);
      buf[HEAD + len] = '}';
      buf[HEAD + len + 1] = '\0';
      ws.textAll(buf);
#endif
    }

    void addToJsonInfo(JsonObject& root) override {
#ifdef WLED_ENABLE_WEBSOCKETS
      root[F("gmr")] = 1;
#endif
    }
};

static GameRelayUsermod gameRelayUsermod;
REGISTER_USERMOD(gameRelayUsermod);
